def sponsorship_signal(company):
    history = get_h1b_filing_history(company)      # USCIS LCA / H-1B disclosure data
    if history.filing_count == 0 and company.tier != 'faang':
        return {'value': 'unknown', 'confidence': 'low',
                'note': 'No filings — likely data sparsity, not confirmed non-sponsorship'}
    if history.filing_count == 0 and company.tier == 'faang':
        return {'value': 'non_sponsor', 'confidence': 'high', 'note': 'FAANG absence is informative'}
    return {'value': 'sponsor', 'confidence': 'high' if history.filing_count >= 3 else 'medium',
            'note': f'{history.filing_count} filings, weighted by recency'}
